#!/usr/bin/env python3
import json
from pathlib import Path

def parse_agent_file(filepath):
    content = filepath.read_text(encoding="utf-8")
    if content.startswith("---"):
        parts = content.split("---", 2)
        if len(parts) >= 3:
            frontmatter = parts[1]
            body = parts[2]
            metadata = {"name": None, "category": None, "marker": None}
            for line in frontmatter.strip().splitlines():
                if ":" in line:
                    key, value = line.split(":", 1)
                    metadata[key.strip()] = value.strip()
            return {**metadata, "description": body.strip() if body.strip() else ""}
    return None

def index_agents():
    workspace = Path(".").resolve()
    index_dir = Path(".claude/skills/agent-registry")
    index_file = index_dir / "index.json"
    agent_dirs = [workspace / "agents", workspace / ".claude" / "agents"]
    agents = []
    seen_names = set()
    for agent_dir in agent_dirs:
        if not agent_dir.exists():
            continue
        for filepath in agent_dir.glob("*.md"):
            metadata = parse_agent_file(filepath)
            if metadata and metadata.get("name"):
                if metadata["name"] not in seen_names:
                    seen_names.add(metadata["name"])
                    agents.append({
                        "name": metadata["name"],
                        "category": metadata.get("category", "general"),
                        "marker": metadata.get("marker"),
                        "description": metadata.get("description", ""),
                        "path": str(filepath.relative_to(workspace))
                    })
    agents.sort(key=lambda x: x["name"])
    index_data = {"version": "1.0", "count": len(agents), "agents": agents}
    index_dir.mkdir(parents=True, exist_ok=True)
    with open(index_file, "w", encoding="utf-8") as f:
        json.dump(index_data, f, indent=2)
    print(f"Indexed {len(agents)} agents to {index_file}")
    return agents

if __name__ == "__main__":
    index_agents()
ENDSCRIPT
